$tabs=New-Object Windows.Forms.TabControl;$tabs.Location=New-Object Drawing.Point(18,78);$tabs.Size=New-Object Drawing.Size(928,570);$form.Controls.Add($tabs);$fields=@{}
function Tab($t){$p=New-Object Windows.Forms.TabPage;$p.Text=$t;$p.AutoScroll=$true;$tabs.TabPages.Add($p);return $p}
function Field($p,$k,$label,$unit,$y,$min,$max,$dp=2){$l=New-Object Windows.Forms.Label;$l.Text=$label;$l.Location=New-Object Drawing.Point(24,$y);$l.Size=New-Object Drawing.Size(430,28);$p.Controls.Add($l);$b=New-Object Windows.Forms.NumericUpDown;$b.Name=$k;$b.Location=New-Object Drawing.Point(470,($y-2));$b.Size=New-Object Drawing.Size(150,28);$b.Minimum=$min;$b.Maximum=$max;$b.DecimalPlaces=$dp;$b.Increment=if($dp -eq 0){1}else{0.1};$b.Value=[decimal]$config.$k;$p.Controls.Add($b);$u=New-Object Windows.Forms.Label;$u.Text=$unit;$u.Location=New-Object Drawing.Point(635,$y);$u.AutoSize=$true;$p.Controls.Add($u);$fields[$k]=$b}
function Note($p,$t,$y){$n=New-Object Windows.Forms.Label;$n.Text=$t;$n.Location=New-Object Drawing.Point(24,$y);$n.Size=New-Object Drawing.Size(820,55);$p.Controls.Add($n)}
