for($i=0;$i -lt 4;$i++){ $y=92+$i*58;$l=New-Object Windows.Forms.Label;$l.Text="Ô $($i+1) (X, Y, Z, góc)";$l.Location=New-Object Drawing.Point(24,$y);$l.Size=New-Object Drawing.Size(200,28);$p.Controls.Add($l);for($j=0;$j -lt 4;$j++){$b=New-Object Windows.Forms.NumericUpDown;$b.Location=New-Object Drawing.Point((235+$j*145),($y-2));$b.Size=New-Object Drawing.Size(125,28);$b.Minimum=-1000;$b.Maximum=1000;$b.DecimalPlaces=3;$b.Value=[decimal]$config.inbound_pickup_slots[$i][$j];$p.Controls.Add($b);$fields["slot_${i}_${j}"]=$b}}
$save=New-Object Windows.Forms.Button;$save.Text='Lưu cấu hình';$save.Location=New-Object Drawing.Point(720,668);$save.Size=New-Object Drawing.Size(150,38);$save.Add_Click({foreach($k in $fields.Keys){if($k -notlike 'slot_*'){$config.$k=[double]$fields[$k].Value}};$slots=@();for($i=0;$i -lt 4;$i++){$row=@();for($j=0;$j -lt 4;$j++){$row += [double]$fields["slot_${i}_${j}"].Value};$slots+=,$row};$config.inbound_pickup_slots=$slots;if($config.agv_following_gap_m -lt .25){[Windows.Forms.MessageBox]::Show('Khoảng cách AGV phải >= 0.25 m.');return};[IO.File]::WriteAllText($path,($config|ConvertTo-Json -Depth 20),(New-Object Text.UTF8Encoding($false)));[Windows.Forms.MessageBox]::Show('Đã lưu. Hãy khởi động lại mô phỏng để áp dụng.','Hoàn tất')});$form.Controls.Add($save);[void]$form.ShowDialog()
